<script lang="ts">
  import { invoke } from '@tauri-apps/api/core';
  import { open } from '@tauri-apps/plugin-dialog';
  import GeometryView from './lib/GeometryView.svelte';
  import ContourOverlay from './lib/ContourOverlay.svelte';
  import PreflightPanel from './lib/PreflightPanel.svelte';
  import FacingPreflightPanel from './lib/FacingPreflightPanel.svelte';
  import CarvePreflightPanel from './lib/CarvePreflightPanel.svelte';
  import DrillPreflightPanel from './lib/DrillPreflightPanel.svelte';
  import JobPreflightPanel from './lib/JobPreflightPanel.svelte';
  import GCodePanel from './lib/GCodePanel.svelte';
  import FacingGCodePanel from './lib/FacingGCodePanel.svelte';
  import PocketGCodePanel from './lib/PocketGCodePanel.svelte';
  import CarveGCodePanel from './lib/CarveGCodePanel.svelte';
  import DrillGCodePanel from './lib/DrillGCodePanel.svelte';
  import FeedsSpeedsCalculator from './lib/FeedsSpeedsCalculator.svelte';
  import type { MillingToolKind } from './lib/toolTypes';
  import type { Curve2, ImportSummary, StockDefinition, StockMode, PartPlacement, PartOrientation, WorkCoordinateSystem, CamOperation, FacingOperation, ContourOperation, PocketOperation, CarveOperation, DrillOperation, OperationKind, CarveSelectionMode, DrillSelectionMode, OperationsProject } from './lib/types';
  import { defaultStock, defaultPartPlacement, defaultPartOrientation, defaultWcs, defaultFacingOperation, defaultContourOperation, defaultPocketOperation, defaultCarveOperation, defaultDrillOperation, defaultOperationsProject } from './lib/types';
  import { activeOperation, addOperation, cloneOperation, operationSummary, removeOperation, replaceOperation, selectOperation } from './lib/operationsProject';

  const steps = ['Bauteil', 'Rohling', 'Werkzeuge', 'Bearbeiten', 'Prüfen', 'Fräsen'];
  let activeStep = 'Bauteil';
  let importSummary: ImportSummary | null = null;
  let stock: StockDefinition = { ...defaultStock };
  let stockMode: StockMode = 'manual';
  let placement: PartPlacement = { ...defaultPartPlacement };
  let orientation: PartOrientation = { ...defaultPartOrientation };
  let wcs: WorkCoordinateSystem = { ...defaultWcs };
  let operationsProject:OperationsProject={operations:defaultOperationsProject.operations.map(cloneOperation),activeOperationId:defaultOperationsProject.activeOperationId};
  let operation: CamOperation = cloneOperation(activeOperation(operationsProject)??defaultContourOperation);
  let error = '';

  const operationLabel=(kind:OperationKind)=>kind==='facing'?'Planen':kind==='contour'?'Kontur':kind==='pocket'?'Tasche':kind==='carve'?'Carve':'Bohren';
  function setOperation(next:CamOperation){operation=cloneOperation(next);operationsProject=replaceOperation(operationsProject,operation);}
  function updateFacing(patch:Partial<FacingOperation>){if(operation.kind!=='facing')return;setOperation({...operation,...patch});}
  function updateContour(patch:Partial<ContourOperation>){if(operation.kind!=='contour')return;setOperation({...operation,...patch});}
  function updatePocket(patch:Partial<PocketOperation>){if(operation.kind!=='pocket')return;setOperation({...operation,...patch});}
  function updateDrill(patch:Partial<DrillOperation>){if(operation.kind!=='drill')return;setOperation({...operation,...patch});}
  function activateOperation(id:string){operationsProject=selectOperation(operationsProject,id);const next=activeOperation(operationsProject);if(next)operation=cloneOperation(next);}
  function appendOperation(kind:OperationKind){operationsProject=addOperation(operationsProject,kind);const next=activeOperation(operationsProject);if(next)operation=cloneOperation(next);}
  function deleteOperation(id:string){if(operationsProject.operations.length<=1)return;operationsProject=removeOperation(operationsProject,id);const next=activeOperation(operationsProject);if(next)operation=cloneOperation(next);}
  function resetOperations(){operationsProject={operations:[cloneOperation(defaultContourOperation)],activeOperationId:defaultContourOperation.id};operation=cloneOperation(defaultContourOperation);}
  function applyToolOperationTransfer(transfer:{toolId:string;toolName:string;toolKind:MillingToolKind;diameterMm:number;feedMmMin:number;spindleRpm:number}){
    if(!(transfer.diameterMm>0&&transfer.feedMmMin>0&&transfer.spindleRpm>0))return;
    setOperation({...operation,tool:{id:transfer.toolId,name:transfer.toolName,diameterMm:transfer.diameterMm,kind:transfer.toolKind},feedMmMin:transfer.feedMmMin,spindleRpm:transfer.spindleRpm} as CamOperation);
  }

  function updateStock(field: 'width' | 'height' | 'thickness', event: Event) { if (stockMode !== 'manual' && !(importSummary?.kind === 'dxf' && stockMode === 'part-bounds' && field === 'thickness')) return; const value=Number((event.currentTarget as HTMLInputElement).value);if(Number.isFinite(value)&&value>0)stock={...stock,[field]:value}; }
  function updatePlacementOffset(field:'offsetX'|'offsetY'|'offsetZ',event:Event){const value=Number((event.currentTarget as HTMLInputElement).value);if(Number.isFinite(value))placement={...placement,[field]:value};}
  function updateNumber(field:'totalDepthMm'|'stepDownMm'|'feedMmMin'|'plungeMmMin'|'spindleRpm'|'safeZMm',event:Event){const value=Number((event.currentTarget as HTMLInputElement).value);if(Number.isFinite(value))setOperation({...operation,[field]:value} as CamOperation);}
  function updateToolDiameter(event:Event){const value=Number((event.currentTarget as HTMLInputElement).value);if(Number.isFinite(value)&&value>0)setOperation({...operation,tool:{...operation.tool,diameterMm:value}} as CamOperation);}
  function updateFacingStepover(event:Event){if(operation.kind!=='facing')return;const value=Number((event.currentTarget as HTMLInputElement).value);if(Number.isFinite(value))setOperation({...operation,stepoverPercent:value});}
  function updatePocketStepover(event:Event){if(operation.kind!=='pocket')return;const value=Number((event.currentTarget as HTMLInputElement).value);if(Number.isFinite(value))setOperation({...operation,stepoverPercent:value});}
  function updateRampAngle(event:Event){if(operation.kind!=='pocket')return;const value=Number((event.currentTarget as HTMLInputElement).value);if(Number.isFinite(value))setOperation({...operation,rampAngleDeg:value});}
  function selectContour(id:number){if(operation.kind==='facing'||operation.kind==='carve'||operation.kind==='drill')return;setOperation({...operation,contourId:id});}
  function eligibleCarveCurve(curve:Curve2){return curve.kind==='line'||curve.kind==='arc'||(curve.kind==='polyline'&&!curve.closed);}
  function carveLayerNames(){if(importSummary?.kind!=='dxf')return[];const curves=importSummary.planarGeometry?.curves??[],layers=importSummary.planarGeometry?.curveLayers??[];return [...new Set(curves.map((curve,i)=>eligibleCarveCurve(curve)?layers[i]:null).filter((v):v is string=>!!v))].sort((a,b)=>a.localeCompare(b));}
  function carveLayerEligibleCount(name:string|null){if(!name||importSummary?.kind!=='dxf')return 0;const curves=importSummary.planarGeometry?.curves??[],layers=importSummary.planarGeometry?.curveLayers??[];return curves.reduce((n,curve,i)=>n+(layers[i]===name&&eligibleCarveCurve(curve)?1:0),0);}
  function setCarveSelectionMode(mode:CarveSelectionMode){if(operation.kind!=='carve')return;setOperation({...operation,selectionMode:mode,curveIds:[],layerName:null});}
  function toggleCarveCurve(id:number){if(operation.kind!=='carve')return;const set=new Set(operation.curveIds);set.has(id)?set.delete(id):set.add(id);setOperation({...operation,curveIds:[...set].sort((a,b)=>a-b)});}
  function chooseCarveLayer(event:Event){if(operation.kind!=='carve'||!importSummary?.planarGeometry)return;const name=(event.currentTarget as HTMLSelectElement).value||null;const curves=importSummary.planarGeometry.curves,layers=importSummary.planarGeometry.curveLayers??[];const curveIds=name?curves.flatMap((curve,i)=>layers[i]===name&&eligibleCarveCurve(curve)?[i]:[]):[];setOperation({...operation,layerName:name,curveIds});}
  function drillLayerNames(){if(importSummary?.kind!=='dxf')return[];const curves=importSummary.planarGeometry?.curves??[],layers=importSummary.planarGeometry?.curveLayers??[];return [...new Set(curves.map((curve,i)=>curve.kind==='circle'?layers[i]:null).filter((v):v is string=>!!v))].sort((a,b)=>a.localeCompare(b));}
  function drillLayerEligibleCount(name:string|null){if(!name||importSummary?.kind!=='dxf')return 0;const curves=importSummary.planarGeometry?.curves??[],layers=importSummary.planarGeometry?.curveLayers??[];return curves.reduce((n,curve,i)=>n+(layers[i]===name&&curve.kind==='circle'?1:0),0);}
  function setDrillSelectionMode(mode:DrillSelectionMode){if(operation.kind!=='drill')return;setOperation({...operation,selectionMode:mode,curveIds:[],layerName:null});}
  function toggleDrillCurve(id:number){if(operation.kind!=='drill'||importSummary?.planarGeometry?.curves[id]?.kind!=='circle')return;const set=new Set(operation.curveIds);set.has(id)?set.delete(id):set.add(id);setOperation({...operation,curveIds:[...set].sort((a,b)=>a-b)});}
  function chooseDrillLayer(event:Event){if(operation.kind!=='drill'||!importSummary?.planarGeometry)return;const name=(event.currentTarget as HTMLSelectElement).value||null;const curves=importSummary.planarGeometry.curves,layers=importSummary.planarGeometry.curveLayers??[];const curveIds=name?curves.flatMap((curve,i)=>layers[i]===name&&curve.kind==='circle'?[i]:[]):[];setOperation({...operation,layerName:name,curveIds});}
  function setOperationKind(kind:OperationKind){
    if(kind===operation.kind)return;
    const common={id:operation.id,name:operation.name,enabled:operation.enabled,tool:{...operation.tool},totalDepthMm:operation.totalDepthMm,stepDownMm:operation.stepDownMm,feedMmMin:operation.feedMmMin,plungeMmMin:operation.plungeMmMin,spindleRpm:operation.spindleRpm,safeZMm:operation.safeZMm};
    const contourId=(operation.kind==='facing'||operation.kind==='carve'||operation.kind==='drill')?null:operation.contourId;
    if(kind==='facing')setOperation({...defaultFacingOperation,...common,tool:{...defaultFacingOperation.tool}});
    else if(kind==='contour')setOperation({...defaultContourOperation,...common,contourId});
    else if(kind==='pocket')setOperation({...defaultPocketOperation,...common,contourId});
    else if(kind==='drill')setOperation({...defaultDrillOperation,...common,tool:{...defaultDrillOperation.tool},curveIds:[]});
    else setOperation({...defaultCarveOperation,...common,tool:{...defaultCarveOperation.tool},curveIds:[]});
  }

  function curvePoints(curve:Curve2){if(curve.kind==='line')return[curve.start,curve.end];if(curve.kind==='polyline')return curve.points;if(curve.kind==='circle')return Array.from({length:65},(_,i)=>{const a=i/64*Math.PI*2;return{x:curve.center.x+Math.cos(a)*curve.radius,y:curve.center.y+Math.sin(a)*curve.radius}});if(curve.kind==='arc'){let a=curve.startAngleDeg,b=curve.endAngleDeg;while(b<a)b+=360;return Array.from({length:65},(_,i)=>{const r=(a+(b-a)*i/64)*Math.PI/180;return{x:curve.center.x+Math.cos(r)*curve.radius,y:curve.center.y+Math.sin(r)*curve.radius}})}return[];}
  function orientedPartSize(angleDeg=orientation.rotationZDeg){if(!importSummary)return null;const a=angleDeg*Math.PI/180,c=Math.cos(a),s=Math.sin(a);let points:{x:number;y:number;z:number}[]=[];if(importSummary.kind==='step'){const v=importSummary.brep?.displayVertices??[];for(let i=0;i+2<v.length;i+=3)points.push({x:v[i],y:v[i+1],z:v[i+2]})}else points=(importSummary.planarGeometry?.curves??[]).flatMap(curvePoints).map(p=>({...p,z:0}));if(!points.length)return null;const rotated=points.map(p=>({x:p.x*c-p.y*s,y:p.x*s+p.y*c,z:p.z})),xs=rotated.map(p=>p.x),ys=rotated.map(p=>p.y),zs=rotated.map(p=>p.z);return{width:Math.max(...xs)-Math.min(...xs),height:Math.max(...ys)-Math.min(...ys),thickness:importSummary.kind==='step'?Math.max(...zs)-Math.min(...zs):stock.thickness}}
  function applyPartBounds(angleDeg=orientation.rotationZDeg){const size=orientedPartSize(angleDeg);if(!size)return;stock={...stock,width:size.width,height:size.height,thickness:size.thickness};placement={...defaultPartPlacement};}
  function setStockMode(mode:StockMode){if(mode==='none'&&importSummary?.kind!=='dxf')return;stockMode=mode;if(mode==='part-bounds')applyPartBounds();if(mode==='none')placement={...defaultPartPlacement};}
  function setRotationZ(value:number){orientation={...orientation,rotationZDeg:value};if(stockMode==='part-bounds')applyPartBounds(value);}
  function updateRotationZ(event:Event){const value=Number((event.currentTarget as HTMLInputElement).value);if(Number.isFinite(value))setRotationZ(value);}
  async function importPart(){error='';const path=await open({multiple:false,directory:false,filters:[{name:'CAD',extensions:['step','stp','dxf']}]});if(!path||Array.isArray(path))return;try{importSummary=await invoke<ImportSummary>('inspect_import',{path});stockMode='manual';placement={...defaultPartPlacement};orientation={...defaultPartOrientation};wcs={...defaultWcs};resetOperations()}catch(e){error=String(e)}}
</script>

<div class="app-shell">
<header class="topbar"><div><strong>BeBlog CAM</strong><span class="build">001V</span></div><div class="project-name">{importSummary?.fileName??'Neues Projekt'}</div></header>
<aside class="rail" aria-label="Arbeitsablauf">{#each steps as step,i}<button class:active={activeStep===step} onclick={()=>activeStep=step}><span>{String(i+1).padStart(2,'0')}</span>{step}</button>{/each}</aside>
<main class="workspace"><section class="viewport">
{#if importSummary}{#key `${importSummary.kind}:${stockMode}:${stock.width}:${stock.height}:${stock.thickness}:${placement.horizontal}:${placement.vertical}:${placement.offsetX}:${placement.offsetY}:${placement.offsetZ}:${orientation.rotationZDeg}:${wcs.x}:${wcs.y}:${wcs.z}`}<GeometryView summary={importSummary} {stock} {stockMode} {placement} {orientation} {wcs}/>{/key}{#if activeStep==='Bearbeiten'&&importSummary.kind==='dxf'&&operation.kind!=='facing'}<ContourOverlay summary={importSummary} {stock} {stockMode} {placement} {orientation} {operation} onSelectContour={selectContour} onSelectCarveCurve={toggleCarveCurve} onSelectDrillCurve={toggleDrillCurve}/>{/if}<div class="view-label">Aufspannebene → {stockMode==='none'?'Bauteil':'Rohling → Bauteil'} → WCS</div>{:else}<div class="empty-state"><div class="mark">B</div><h1>Ein Bauteil öffnen</h1><p>STEP für exakte 3D-BRep-Geometrie oder DXF für planare Konturen.</p><button class="primary" onclick={importPart}>Bauteil öffnen</button></div>{/if}
</section><aside class="inspector">
{#if activeStep==='Bauteil'}<p class="eyebrow">01 · Bauteil</p><h2>Geometrie</h2>{#if importSummary}<dl><div><dt>Datei</dt><dd>{importSummary.fileName}</dd></div><div><dt>Format</dt><dd>{importSummary.kind.toUpperCase()}</dd></div><div><dt>Backend</dt><dd>{importSummary.backend}</dd></div><div><dt>Status</dt><dd>{importSummary.status==='ready'?'Bereit':'Native STEP-Anbindung fehlt in diesem Build'}</dd></div></dl><div class="placement-section"><p class="placement-title">Modellorientierung</p><div class="placement-grid"><button class:active={orientation.rotationZDeg===0} onclick={()=>setRotationZ(0)}>0°</button><button class:active={orientation.rotationZDeg===90} onclick={()=>setRotationZ(90)}>90°</button><button class:active={orientation.rotationZDeg===180} onclick={()=>setRotationZ(180)}>180°</button></div><div class="placement-grid two"><button class:active={orientation.rotationZDeg===270} onclick={()=>setRotationZ(270)}>270°</button><button onclick={()=>setRotationZ(0)}>Zurücksetzen</button></div><label>Rotation Z <input type="number" step="1" value={orientation.rotationZDeg} oninput={updateRotationZ}/> °</label><p class="note">Das dreht das Bauteil wirklich relativ zur Aufspannung. Die freie Mausrotation verändert nur die Kamera.</p></div>{#if Object.keys(importSummary.entities).length}<div class="entity-list">{#each Object.entries(importSummary.entities) as [name,count]}<span>{name} <b>{count}</b></span>{/each}</div>{/if}{#if importSummary.note}<p class="note">{importSummary.note}</p>{/if}<button class="secondary" onclick={importPart}>Anderes Bauteil öffnen</button>{:else}<p>Das CAD-Modell ist die Quelle für alle späteren Bearbeitungen.</p><button class="primary" onclick={importPart}>Bauteil öffnen</button>{/if}
{:else if activeStep==='Rohling'}<p class="eyebrow">02 · Rohling</p><h2>Rohling</h2><div class="placement-section"><p class="placement-title">Rohling entsteht aus</p><div class="placement-grid"><button class:active={stockMode==='manual'} onclick={()=>setStockMode('manual')}>Maßen</button><button class:active={stockMode==='part-bounds'} onclick={()=>setStockMode('part-bounds')}>Bauteil</button>{#if importSummary?.kind==='dxf'}<button class:active={stockMode==='none'} onclick={()=>setStockMode('none')}>Kein Rohling</button>{/if}</div></div>{#if stockMode!=='none'}<label>Breite <input type="number" min="0.1" step="0.1" value={stock.width} disabled={stockMode==='part-bounds'} oninput={e=>updateStock('width',e)}/> mm</label><label>Länge <input type="number" min="0.1" step="0.1" value={stock.height} disabled={stockMode==='part-bounds'} oninput={e=>updateStock('height',e)}/> mm</label><label>Dicke <input type="number" min="0.1" step="0.1" value={stock.thickness} disabled={stockMode==='part-bounds'&&importSummary?.kind==='step'} oninput={e=>updateStock('thickness',e)}/> mm</label><div class="placement-section"><p class="placement-title">Bauteil im Rohling</p><div class="placement-grid"><button class:active={placement.horizontal==='left'} onclick={()=>placement={...placement,horizontal:'left'}}>Links</button><button class:active={placement.horizontal==='center'} onclick={()=>placement={...placement,horizontal:'center'}}>Zentriert</button><button class:active={placement.horizontal==='right'} onclick={()=>placement={...placement,horizontal:'right'}}>Rechts</button></div><div class="placement-grid"><button class:active={placement.vertical==='front'} onclick={()=>placement={...placement,vertical:'front'}}>Vorne</button><button class:active={placement.vertical==='center'} onclick={()=>placement={...placement,vertical:'center'}}>Mitte</button><button class:active={placement.vertical==='back'} onclick={()=>placement={...placement,vertical:'back'}}>Hinten</button></div><details><summary>Feinkorrektur</summary><label>X <input type="number" step="0.1" value={placement.offsetX} oninput={e=>updatePlacementOffset('offsetX',e)}/> mm</label><label>Y <input type="number" step="0.1" value={placement.offsetY} oninput={e=>updatePlacementOffset('offsetY',e)}/> mm</label><label>Z <input type="number" step="0.1" value={placement.offsetZ} oninput={e=>updatePlacementOffset('offsetZ',e)}/> mm</label></details></div>{:else}<p class="note"><strong>Kein Rohling.</strong> Die DXF wird direkt als planare Bauteilgeometrie verwendet.</p>{/if}<div class="placement-section"><p class="placement-title">Werkstücknullpunkt / WCS</p><div class="placement-grid"><button class:active={wcs.x==='left'} onclick={()=>wcs={...wcs,x:'left'}}>Links</button><button class:active={wcs.x==='center'} onclick={()=>wcs={...wcs,x:'center'}}>Mitte</button><button class:active={wcs.x==='right'} onclick={()=>wcs={...wcs,x:'right'}}>Rechts</button></div><div class="placement-grid"><button class:active={wcs.y==='front'} onclick={()=>wcs={...wcs,y:'front'}}>Vorne</button><button class:active={wcs.y==='center'} onclick={()=>wcs={...wcs,y:'center'}}>Mitte</button><button class:active={wcs.y==='back'} onclick={()=>wcs={...wcs,y:'back'}}>Hinten</button></div><div class="placement-grid two"><button class:active={wcs.z==='top'} onclick={()=>wcs={...wcs,z:'top'}}>Oberseite</button><button class:active={wcs.z==='bottom'} onclick={()=>wcs={...wcs,z:'bottom'}}>Unterseite</button></div></div>
{:else if activeStep==='Werkzeuge'}<FeedsSpeedsCalculator activeOperationName={operation.name} onApplyToOperation={applyToolOperationTransfer}/>
{:else if activeStep==='Bearbeiten'}<p class="eyebrow">04 · Bearbeiten</p><h2>{operationLabel(operation.kind)}</h2>{#if importSummary}
<div class="placement-section"><p class="placement-title">Bearbeitungen</p><div class="operation-list">{#each operationsProject.operations as op,i}<div class:current-operation={op.id===operationsProject.activeOperationId} class="operation-row"><button class="operation-select" onclick={()=>activateOperation(op.id)}><span class="operation-index">{String(i+1).padStart(2,'0')}</span><span><strong>{operationLabel(op.kind)}</strong><small>{operationSummary(op)}</small></span></button>{#if operationsProject.operations.length>1}<button class="operation-delete" aria-label={`${op.name} löschen`} title="Bearbeitung löschen" onclick={()=>deleteOperation(op.id)}>×</button>{/if}</div>{/each}</div><div class="operation-add"><span>+ Bearbeitung</span><button onclick={()=>appendOperation('facing')}>Planen</button><button onclick={()=>appendOperation('contour')}>Kontur</button><button onclick={()=>appendOperation('pocket')}>Tasche</button><button onclick={()=>appendOperation('carve')}>Carve</button><button onclick={()=>appendOperation('drill')}>Bohren</button></div></div>
<div class="placement-section"><p class="placement-title">Aktive Bearbeitung</p><div class="placement-grid two"><button class:active={operation.kind==='facing'} onclick={()=>setOperationKind('facing')}>Planen</button><button class:active={operation.kind==='contour'} onclick={()=>setOperationKind('contour')}>Kontur</button></div><div class="placement-grid two"><button class:active={operation.kind==='pocket'} onclick={()=>setOperationKind('pocket')}>Tasche</button><button class:active={operation.kind==='carve'} onclick={()=>setOperationKind('carve')}>Carve</button></div><div class="placement-grid two"><button class:active={operation.kind==='drill'} onclick={()=>setOperationKind('drill')}>Bohren</button></div></div>
{#if operation.kind==='facing'}<p>Die komplette rechteckige Rohlingoberseite wird geplant. Es ist keine Geometrieauswahl erforderlich.</p><p class="note"><strong>Ziel:</strong> {stock.width.toFixed(3)} × {stock.height.toFixed(3)} mm Rohlingfläche · Z-Null auf Oberseite erforderlich.</p>
{:else if operation.kind==='carve'}<p>{importSummary.kind==='dxf'?'Wähle offene DXF-Geometrien einzeln oder gemeinsam über ihre Ebene.':'Carve aus STEP folgt später.'}</p>{#if importSummary.kind==='dxf'}<div class="placement-section"><p class="placement-title">Geometrie auswählen</p><div class="placement-grid two"><button class:active={operation.selectionMode==='individual'} onclick={()=>setCarveSelectionMode('individual')}>Einzeln</button><button class:active={operation.selectionMode==='layer'} onclick={()=>setCarveSelectionMode('layer')}>Ebene</button></div>{#if operation.selectionMode==='layer'}<label>Ebene <select value={operation.layerName??''} onchange={chooseCarveLayer}><option value="">Ebene wählen …</option>{#each carveLayerNames() as layer}<option value={layer}>{layer}</option>{/each}</select></label>{/if}<p class="note"><strong>Auswahl:</strong> {operation.curveIds.length}{operation.layerName?` von ${carveLayerEligibleCount(operation.layerName)}`:''} offene Geometrie{operation.curveIds.length===1?'':'n'}{operation.layerName?` · Ebene ${operation.layerName}`:''}.</p>{#if operation.selectionMode==='layer'&&operation.layerName}<p class="note">Die Ebene ist die Vorauswahl. Klicke markierte Geometrien im Viewport an, um einzelne Elemente auszuschließen; erneuter Klick fügt sie wieder hinzu.</p>{/if}</div>{/if}
{:else if operation.kind==='drill'}<p>{importSummary.kind==='dxf'?'Wähle native DXF-Kreise als Bohrungen. Der Kreis definiert Mittelpunkt und Soll-Durchmesser; danach wählst du das Herstellungsverfahren.':'Bohrauswahl aus STEP folgt später.'}</p>{#if importSummary.kind==='dxf'}<div class="placement-section"><p class="placement-title">Bohrungen auswählen</p><div class="placement-grid two"><button class:active={operation.selectionMode==='individual'} onclick={()=>setDrillSelectionMode('individual')}>Einzeln</button><button class:active={operation.selectionMode==='layer'} onclick={()=>setDrillSelectionMode('layer')}>Ebene</button></div>{#if operation.selectionMode==='layer'}<label>Ebene <select value={operation.layerName??''} onchange={chooseDrillLayer}><option value="">Ebene wählen …</option>{#each drillLayerNames() as layer}<option value={layer}>{layer}</option>{/each}</select></label>{/if}<p class="note"><strong>Auswahl:</strong> {operation.curveIds.length}{operation.layerName?` von ${drillLayerEligibleCount(operation.layerName)}`:''} Bohrung{operation.curveIds.length===1?'':'en'}{operation.layerName?` · Ebene ${operation.layerName}`:''}.</p>{#if operation.selectionMode==='layer'&&operation.layerName}<p class="note">Die Ebene ist nur die Vorauswahl. Einzelne Kreise lassen sich im Viewport wieder entfernen oder hinzufügen.</p>{/if}</div>{/if}
{:else}<p>{importSummary.kind==='dxf'?'Klicke im Viewport auf eine geschlossene Kontur.':'Die 2D-Auswahl aus STEP folgt später.'}</p>{#if importSummary.kind==='dxf'}<p class="note"><strong>Ziel:</strong> {operation.contourId===null?'Noch keine geschlossene Kontur gewählt.':`Kontur ${operation.contourId+1} gewählt.`}</p>{/if}{/if}
<div class="placement-section"><p class="placement-title">Werkzeug</p><label>Durchmesser <input type="number" min="0.1" step="0.1" value={operation.tool.diameterMm} oninput={updateToolDiameter}/> mm</label>{#if operation.tool.kind}<p class="note">Werkzeugtyp aus Bibliothek: <strong>{operation.tool.kind==='face-mill'?'Planfräser':operation.tool.kind==='end-mill'?'Schaftfräser':operation.tool.kind==='ball-nose'?'Vollradiusfräser':'V-Fräser'}</strong>.</p>{/if}</div>
{#if operation.kind==='facing'}<div class="placement-section"><p class="placement-title">Planstrategie</p><div class="placement-grid two"><button class:active={operation.direction==='x'} onclick={()=>updateFacing({direction:'x'})}>Bahnen in X</button><button class:active={operation.direction==='y'} onclick={()=>updateFacing({direction:'y'})}>Bahnen in Y</button></div><label>Seitliche Zustellung <input type="number" min="5" max="90" step="5" value={operation.stepoverPercent} oninput={updateFacingStepover}/> % Werkzeugdurchmesser</label><p class="note">Zickzack ohne Rapid-Bewegung im Material. Die Stirnkanten werden um einen Werkzeugradius überfahren, damit die gesamte Rohlingfläche abgedeckt wird.</p></div>
{:else if operation.kind==='contour'}<div class="placement-section"><p class="placement-title">Bahn</p><div class="placement-grid"><button class:active={operation.side==='outside'} onclick={()=>updateContour({side:'outside'})}>Außen</button><button class:active={operation.side==='inside'} onclick={()=>updateContour({side:'inside'})}>Innen</button><button class:active={operation.side==='on-line'} onclick={()=>updateContour({side:'on-line'})}>Auf Linie</button></div><div class="placement-grid two"><button class:active={operation.direction==='climb'} onclick={()=>updateContour({direction:'climb'})}>Gleichlauf</button><button class:active={operation.direction==='conventional'} onclick={()=>updateContour({direction:'conventional'})}>Gegenlauf</button></div></div>
{:else if operation.kind==='pocket'}<div class="placement-section"><p class="placement-title">Räumstrategie</p><div class="placement-grid two"><button class:active={operation.strategy==='auto'} onclick={()=>updatePocket({strategy:'auto'})}>Automatisch</button><button class:active={operation.strategy==='raster'} onclick={()=>updatePocket({strategy:'raster'})}>Raster</button></div><div class="placement-grid two"><button class:active={operation.strategy==='concentric'} onclick={()=>updatePocket({strategy:'concentric'})}>Kreis</button><button class:active={operation.strategy==='parallel'} onclick={()=>updatePocket({strategy:'parallel'})}>Konturparallel</button></div><p class="note">Automatisch wählt Kreis für native DXF-Kreise, Raster für achsparallele Rechtecke und Konturparallel für unterstützte gemischte LINE/ARC-Konturen.</p></div><div class="placement-section"><p class="placement-title">Ausräumen</p><label>Seitliche Zustellung <input type="number" min="5" max="90" step="5" value={operation.stepoverPercent} oninput={updatePocketStepover}/> % Werkzeugdurchmesser</label><p class="note">Der Wert begrenzt den Abstand benachbarter Raster-, Kreis- oder konturparalleler Bahnen.</p></div><div class="placement-section"><p class="placement-title">Eintauchen</p><div class="placement-grid two"><button class:active={operation.entry==='plunge'} onclick={()=>updatePocket({entry:'plunge'})}>Senkrecht</button><button class:active={operation.entry==='ramp'} onclick={()=>updatePocket({entry:'ramp'})}>Rampe</button></div>{#if operation.entry==='ramp'}<label>Rampenwinkel <input type="number" min="0.5" max="15" step="0.5" value={operation.rampAngleDeg} oninput={updateRampAngle}/> °</label><p class="note">Die lineare Rampe bleibt dem bewiesenen Rasterpfad vorbehalten. Kreis und Konturparallel benötigen zunächst „Senkrecht“.</p>{:else}<p class="note">Senkrechtes Eintauchen mit definiertem Eintauchvorschub.</p>{/if}</div>
{:else if operation.kind==='drill'}<div class="placement-section"><p class="placement-title">Wie soll die Bohrung entstehen?</p><div class="placement-grid two"><button class:active={operation.method==='drill'} onclick={()=>updateDrill({method:'drill'})}>Bohren</button><button class:active={operation.method==='helical-mill'} onclick={()=>updateDrill({method:'helical-mill'})}>Helixfräsen</button></div>{#if operation.method==='drill'}<p class="note">Axiale Herstellung auf dem Kreismittelpunkt mit expliziten G0/G1-Bewegungen. Keine controllerabhängigen G81/G83-Zyklen.</p>{:else}<p class="note">Der DXF-Kreis ist der Soll-Durchmesser. Die Fräsermittelbahn wird automatisch aus (Bohrungs-Ø − Werkzeug-Ø) / 2 berechnet. 001V verwendet native G3-Halbkreise mit simultaner Z-Zustellung.</p>{/if}</div>
{:else}<div class="placement-section"><p class="placement-title">Bahn</p><p class="note"><strong>Centerline:</strong> Die gewählte DXF-Geometrie selbst ist die Fräsermittellinie. Es wird kein Werkzeugradius-Offset erzeugt.</p></div>{/if}
<div class="placement-section"><p class="placement-title">Schnittdaten</p><label>{operation.kind==='facing'?'Planabtrag':'Gesamttiefe'} <input type="number" min="0.01" step="0.1" value={operation.totalDepthMm} oninput={e=>updateNumber('totalDepthMm',e)}/> mm</label><label>{operation.kind==='drill'&&operation.method==='helical-mill'?'Helix-Zustellung / Umdrehung':'Zustellung'} <input type="number" min="0.01" step="0.1" value={operation.stepDownMm} oninput={e=>updateNumber('stepDownMm',e)}/> mm</label><label>Vorschub <input type="number" min="1" step="10" value={operation.feedMmMin} oninput={e=>updateNumber('feedMmMin',e)}/> mm/min</label><label>Eintauchen <input type="number" min="1" step="10" value={operation.plungeMmMin} oninput={e=>updateNumber('plungeMmMin',e)}/> mm/min</label><label>Drehzahl <input type="number" min="1" step="100" value={operation.spindleRpm} oninput={e=>updateNumber('spindleRpm',e)}/> 1/min</label><label>Sicherheits-Z <input type="number" min="0.1" step="0.5" value={operation.safeZMm} oninput={e=>updateNumber('safeZMm',e)}/> mm</label></div><p class="note"><strong>001V:</strong> Bohren und Helixfräsen teilen Auswahl, Operation, Werkzeugübergabe, Preflight und Postprozessor-Pipeline.</p>{:else}<p>Noch kein Bauteil geladen.</p>{/if}
{:else if activeStep==='Prüfen'}{#if importSummary}{#if operationsProject.operations.length>1}<JobPreflightPanel summary={importSummary} {stock} {stockMode} {placement} {orientation} {wcs} operations={operationsProject.operations}/>{:else if operation.kind==='facing'}<FacingPreflightPanel {stock} {stockMode} {wcs} operation={operation as FacingOperation}/>{:else if operation.kind==='drill'}<DrillPreflightPanel summary={importSummary} {stock} {stockMode} {wcs} operation={operation as DrillOperation}/>{:else if operation.kind==='carve'}<CarvePreflightPanel summary={importSummary} {stock} {stockMode} operation={operation as CarveOperation}/>{:else}<PreflightPanel summary={importSummary} {stock} {stockMode} operation={operation as ContourOperation|PocketOperation}/>{/if}{:else}<p class="eyebrow">05 · Prüfen</p><h2>Preflight</h2><p>Noch kein Bauteil geladen.</p>{/if}
{:else if activeStep==='Fräsen'}{#if importSummary}{#if operation.kind==='facing'}<FacingGCodePanel summary={importSummary} {stock} {stockMode} {wcs} operation={operation as FacingOperation}/>{:else if operation.kind==='drill'}<DrillGCodePanel summary={importSummary} {stock} {stockMode} {placement} {orientation} {wcs} operation={operation as DrillOperation}/>{:else if operation.kind==='contour'}<GCodePanel summary={importSummary} {stock} {stockMode} {placement} {orientation} {wcs} operation={operation as ContourOperation}/>{:else if operation.kind==='pocket'}<PocketGCodePanel summary={importSummary} {stock} {stockMode} {placement} {orientation} {wcs} operation={operation as PocketOperation}/>{:else}<CarveGCodePanel summary={importSummary} {stock} {stockMode} {placement} {orientation} {wcs} operation={operation as CarveOperation}/>{/if}{:else}<p class="eyebrow">06 · Fräsen</p><h2>G-Code</h2><p>Noch kein Bauteil geladen.</p>{/if}
{:else}<p class="eyebrow">{String(steps.indexOf(activeStep)+1).padStart(2,'0')} · {activeStep}</p><h2>{activeStep}</h2><p>Dieser Schritt wird in den nächsten Builds freigeschaltet.</p>{/if}
</aside></main></div>

<style>
.operation-list{display:grid;gap:6px}.operation-row{display:grid;grid-template-columns:1fr auto;align-items:stretch;border:1px solid #deded8;border-radius:8px;background:#fafaf8;overflow:hidden}.operation-row.current-operation{border-color:#9aa49e;background:#f1f3ef}.operation-select{display:grid;grid-template-columns:28px 1fr;gap:8px;text-align:left;align-items:start;border:0;background:transparent;padding:9px 10px;cursor:pointer;color:#39413d}.operation-select span:last-child{display:grid;gap:2px}.operation-select strong{font-size:.8rem}.operation-select small{font-size:.7rem;color:#747a76;font-weight:400}.operation-index{font-size:.68rem;color:#8a8f8b;padding-top:2px}.operation-delete{border:0;border-left:1px solid #deded8;background:transparent;padding:0 10px;color:#8b5d58;cursor:pointer;font-size:1rem}.operation-add{display:grid;grid-template-columns:1fr repeat(5,auto);gap:5px;align-items:center;margin-top:8px}.operation-add span{font-size:.76rem;color:#696f6b}.operation-add button{border:1px solid #d5d7d2;border-radius:6px;background:#fff;padding:5px 7px;font-size:.7rem;color:#4e5651;cursor:pointer}
</style>
